fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    // Vec<u64> implements Clone, so this makes a deep copy of all elements.
    arr.clone()
}

#[cfg(test)]
mod tests {
    use super::list_deep_clone;

    #[test]
    fn test_empty() {
        let original: Vec<u64> = vec![];
        let copied = list_deep_clone(&original);
        assert_eq!(copied, original);
        // Ensure independence
        // (pushing to original does not affect copied)
        let mut original = original;
        original.push(42);
        assert_eq!(copied, Vec::<u64>::new());
    }

    #[test]
    fn test_non_empty() {
        let original = vec![1, 2, 3, 4, 5];
        let mut copied = list_deep_clone(&original);
        assert_eq!(copied, original);
        // Ensure independence
        copied[0] = 99;
        assert_eq!(original[0], 1);
        assert_eq!(copied[0], 99);
    }
}